mapper.insert:
/*  메뉴화면통계텝 엑셀다운 사유 저장 (insertExcelDownloadHistory) */
INSERT INTO OCUOC_EXDWN_H
( EXDWN_ID
, USER_ID
, MENU_ID
, DOWN_REASON
, FRST_REG_EMPNO
, FRST_REG_DTTM)
VALUES ( SQ_OCUOC_EXDWN_H_01.NEXTVAL
	   , #{userId}
	   , #{menuId}
	   , #{downloadReason}
	   , #{frstRegEmpno}
	   , TO_CHAR(SYSTIMESTAMP,'YYYYMMDDHH24MISS')
	   )

/*  화면별 버튼 감사로그 저장 (insertAuditLog) */
INSERT INTO ocuoc_AUDIT_M
( AUDIT_ID
, USER_ID
, MENU_ID
, BTN_ID
, ACTION_CD
, ACTION_NM
, REQ_IP
, REQ_URL
, FRST_REG_DTTM)
VALUES ( SQ_OCUOC_AUDIT_M_01.NEXTVAL
	   , #{userId}
	   , #{menuId}
	   , #{btnCd}
	   , #{actionCd}
	   , #{actionNm}
	   , #{reqIp}
	   , #{reqUrl}
	   , TO_CHAR(SYSTIMESTAMP,'YYYYMMDDHH24MISS')
	   )

mapper.select:
/* 부서정보 조회 (searchDeptList) */ SELECT A.BR_CD AS "brCd" , A.BR_NM AS "brNm" , CASE WHEN SUBSTR(A.TEL_NO,1,2) = '02' AND LENGTH(A.TEL_NO) = 9 THEN SUBSTR(A.TEL_NO,1,2) ||'-'|| SUBSTR(A.TEL_NO,3,3) ||'-'|| SUBSTR(A.TEL_NO,6,4) WHEN SUBSTR(A.TEL_NO,1,2) = '02' AND LENGTH(A.TEL_NO) = 10 THEN SUBSTR(A.TEL_NO,1,2) ||'-'|| SUBSTR(A.TEL_NO,3,4) ||'-'|| SUBSTR(A.TEL_NO,7,4) WHEN LENGTH(A.TEL_NO) = 10 THEN SUBSTR(A.TEL_NO,1,3) ||'-'|| SUBSTR(A.TEL_NO,4,3) ||'-'|| SUBSTR(A.TEL_NO,7,4) WHEN LENGTH(A.TEL_NO) = 11 THEN SUBSTR(A.TEL_NO,1,3) ||'-'|| SUBSTR(A.TEL_NO,4,4) ||'-'|| SUBSTR(A.TEL_NO,8,4) ELSE A.TEL_NO END AS "telNo" , CASE WHEN SUBSTR(A.FAX_NO,1,2) = '02' AND LENGTH(A.FAX_NO) = 9 THEN SUBSTR(A.FAX_NO,1,2) ||'-'|| SUBSTR(A.FAX_NO,3,3) ||'-'|| SUBSTR(A.FAX_NO,6,4) WHEN SUBSTR(A.FAX_NO,1,2) = '02' AND LENGTH(A.FAX_NO) = 10 THEN SUBSTR(A.FAX_NO,1,2) ||'-'|| SUBSTR(A.FAX_NO,3,4) ||'-'|| SUBSTR(A.FAX_NO,7,4) WHEN LENGTH(A.FAX_NO) = 10 THEN SUBSTR(A.FAX_NO,1,3) ||'-'|| SUBSTR(A.FAX_NO,4,3) ||'-'|| SUBSTR(A.FAX_NO,7,4) WHEN LENGTH(A.FAX_NO) = 11 THEN SUBSTR(A.FAX_NO,1,3) ||'-'|| SUBSTR(A.FAX_NO,4,4) ||'-'|| SUBSTR(A.FAX_NO,8,4) ELSE A.FAX_NO END AS "faxNo" , A.BR_AD AS "brAd" FROM OCUOC_DPRMI_M A WHERE 1=1
AND A.BR_CD like '%'|| #{brCd} || '%'
AND A.BR_NM like '%'|| #{brNm} || '%'
